selector_to_html = {"a[href=\"install.html#verify-the-installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Verify the installation<a class=\"headerlink\" href=\"#verify-the-installation\" title=\"Link to this heading\">#</a></h2><p>The package is imported with <code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">flagquantum</span> <span class=\"pre\">as</span> <span class=\"pre\">fq</span></code>, and importing it does\nnot import optional dependencies, discover extensions, or activate a provider.</p>", "a[href=\"quick-start.html#train-your-first-quantum-model\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Train your first quantum model<a class=\"headerlink\" href=\"#train-your-first-quantum-model\" title=\"Link to this heading\">#</a></h2><p>Build a two-qubit circuit and learn its rotation angle by minimising the\nexpectation value of <code class=\"docutils literal notranslate\"><span class=\"pre\">Z</span></code> on wire 0:</p>", "a[href=\"quick-start.html#next-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Next steps<a class=\"headerlink\" href=\"#next-steps\" title=\"Link to this heading\">#</a></h2>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum runs on Python 3.10 to 3.12 and requires PyTorch 2.5 or newer. The\nreleased package depends on PyTorch only; everything else is an optional extra.</p>", "a[href=\"#getting-started-with-flagquantum\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started with FlagQuantum<a class=\"headerlink\" href=\"#getting-started-with-flagquantum\" title=\"Link to this heading\">#</a></h1><p>This section covers the requirements for installing FlagQuantum, the installation\nitself, and a first trainable quantum model.</p>", "a[href=\"install.html#run-a-local-example\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Run a local example<a class=\"headerlink\" href=\"#run-a-local-example\" title=\"Link to this heading\">#</a></h2><p>The maintained local path needs no credentials, no remote resources, and no\noptional backend:</p>", "a[href=\"quick-start.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h1><p>This page trains a two-qubit model, then shows how to switch the simulation\nrepresentation without editing the model.</p>", "a[href=\"requirements.html#software-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Software requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2><p>Optional extras are declared in <code class=\"docutils literal notranslate\"><span class=\"pre\">pyproject.toml</span></code> and installed with\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span> <span class=\"pre\">install</span> <span class=\"pre\">\"flagquantum[&lt;extra&gt;]\"</span></code>:</p>", "a[href=\"requirements.html#hardware-platforms\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware platforms<a class=\"headerlink\" href=\"#hardware-platforms\" title=\"Link to this heading\">#</a></h2><p>FlagQuantum performs no vendor detection and contains no vendor branches. Physical-device detection, the vendor runtime, and the mapping from <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos:0</span></code> to a physical card belong to the FlagOS provider integration; FlagQuantum records the runtime identity and route evidence it is given. A domestic accelerator is therefore not certified merely because an integration path exists.</p>", "a[href=\"install.html#install-the-development-version\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install the development version<a class=\"headerlink\" href=\"#install-the-development-version\" title=\"Link to this heading\">#</a></h2>", "a[href=\"install.html#install-the-released-package\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install the released package<a class=\"headerlink\" href=\"#install-the-released-package\" title=\"Link to this heading\">#</a></h2>", "a[href=\"install.html#next-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Next steps<a class=\"headerlink\" href=\"#next-steps\" title=\"Link to this heading\">#</a></h2><p>Continue with the <a class=\"reference internal\" href=\"quick-start.html\"><span class=\"std std-doc\">quick start</span></a>, or go straight to\n<a class=\"reference internal\" href=\"#../user_guide/simulation-modes.md\"><span class=\"xref myst\">Simulation modes</span></a> to choose a representation\nand <a class=\"reference internal\" href=\"#../user_guide/remote-execution.md\"><span class=\"xref myst\">Remote execution</span></a> for provider targets.</p>", "a[href=\"requirements.html#multi-node-expectations\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-node expectations<a class=\"headerlink\" href=\"#multi-node-expectations\" title=\"Link to this heading\">#</a></h2><p>Distributed support is environment-specific. In the reviewed setup, a two-node\nA800 deployment with one device per node runs forward, gradient, and\ntraining/resume workloads over NCCL and TCP; multi-node release certification is\na separate, evidence-gated step.</p>", "a[href=\"quick-start.html#inspect-a-circuit-and-its-plan-before-running-it\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Inspect a circuit and its plan before running it<a class=\"headerlink\" href=\"#inspect-a-circuit-and-its-plan-before-running-it\" title=\"Link to this heading\">#</a></h2><p>The plan can be serialised and restored. Passing the restored plan to <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code>\nexecutes exactly that plan: it is not replanned, and it is not silently replaced\nby another backend.</p>", "a[href=\"install.html#optional-dependency-groups\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Optional dependency groups<a class=\"headerlink\" href=\"#optional-dependency-groups\" title=\"Link to this heading\">#</a></h2><p>Install an optional capability only when you need it:</p>", "a[href=\"install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install FlagQuantum<a class=\"headerlink\" href=\"#install-flagquantum\" title=\"Link to this heading\">#</a></h1><p>Read <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a> before proceeding.</p>", "a[href=\"quick-start.html#run-the-same-model-on-another-representation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Run the same model on another representation<a class=\"headerlink\" href=\"#run-the-same-model-on-another-representation\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/quick_start.py</span></code> trains a hybrid classical-quantum model whose exact\nsolution is known, and switches the simulation representation from the command\nline:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
